int kvm_set_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;
    mutex_lock(&kvm->pit_state_mutex);
    kvm->pit_state->flags = ps->flags;
    for (i = 0; i < 3; i++) {
        kvm->pit_state->channels[i] = ps->channels[i];
        if (kvm->pit_state->channels[i].count != 0)
            kvm_pit_load_count(kvm, i);
    }
    kvm->pit_state->hpet = !!(ps->flags & KVM_PIT_FLAGS_HPET);
    mutex_unlock(&kvm->pit_state_mutex);
    return 0;
}

int kvm_set_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;

    mutex_lock(&kvm->pit_state.lock);
    kvm->pit_state.flags &= ~KVM_PIT_FLAGS_HPET_LEGACY;
    kvm->pit_state.flags |= ps->flags & KVM_PIT_FLAGS_HPET_LEGACY;
    for (i = 0; i < 3; i++) {
        kvm->pit_state.channels[i].count = le16_to_cpu(ps->channels[i].count);
        kvm->pit_state.channels[i].latched_count = le16_to_cpu(ps->channels[i].count);
        kvm->pit_state.channels[i].current_count = le16_to_cpu(ps->channels[i].count);
        kvm->pit_state.channels[i].mode = ps->channels[i].mode;
        kvm->pit_state.channels[i].latched_flag = 0;
        kvm->pit_state.channels[i].count_load_time = 0;
        kvm->pit_state.channels[i].count_reload_time = 0;
        kvm->pit_state.channels[i].gate = 1;
        kvm->pit_state.channels[i].speaker = 0;
    }
    mutex_unlock(&kvm->pit_state.lock);
    return 0;
}

int kvm_set_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;

    mutex_lock(&kvm->pit_state->mutex);
    kvm->legacy_hpet = ps->legacy_hpet;
    for (i = 0; i < 3; i++) {
        kvm->pit_state->channels[i].state = ps->channels[i];
        kvm->pit_state->flags = ps->flags;
        kvm_pit_load_count(kvm, i, ps->channels[i].count);
    }
    mutex_unlock(&kvm->pit_state->mutex);

    return 0;
}
